package com.estoqueinteligente.auth;
import java.nio.charset.StandardCharsets;import java.util.Date;import javax.crypto.SecretKey;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.stereotype.Service;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;
@Service public class JwtService{private final SecretKey key;private final long expiration;public JwtService(@Value("${jwt.secret}")String secret,@Value("${jwt.expiration}")long expiration){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;}public String generateToken(UserDetails user){Date now=new Date();return Jwts.builder().subject(user.getUsername()).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();}public String extractUsername(String token){return parse(token).getPayload().getSubject();}public boolean isValid(String token,UserDetails user){Claims claims=parse(token).getPayload();return claims.getSubject().equals(user.getUsername())&&claims.getExpiration().after(new Date());}private Jws<Claims> parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token);}}
